import json
import csv

with open('json/event.json', 'r') as f:
    event_data = json.load(f)
    events = {rec['event_id']: rec['event_name'] for rec in event_data['records']}

budgets = {}
with open('csv/budget.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        budget_id = row['budget_id']
        event_id = row['link_to_event']
        if budget_id not in budgets:
            budgets[budget_id] = {'event_id': event_id, 'spent': float(row['spent'])}

with open('json/expense.json', 'r') as f:
    expense_data = json.load(f)

event_costs = {}
for expense in expense_data['records']:
    link_to_budget = expense['link_to_budget']
    cost = expense['cost']
    if link_to_budget in budgets:
        event_id = budgets[link_to_budget]['event_id']
        if event_id not in event_costs:
            event_costs[event_id] = 0
        event_costs[event_id] += cost

if event_costs:
    min_event_id = min(event_costs, key=event_costs.get)
    min_cost = event_costs[min_event_id]
    min_event_name = events.get(min_event_id, 'Unknown')
    print(f'Event with lowest cost: {min_event_name}')
    print(f'Total cost: {min_cost}')
    sorted_events = sorted(event_costs.items(), key=lambda x: x[1])
    print('\nAll events by cost (lowest first):')
    for eid, cost in sorted_events[:10]:
        print(f'  {events.get(eid, "Unknown")}: {cost}')
else:
    print('No costs found')

